import{_ as s,o as t,c as r,a2 as a}from"./chunks/framework.ChIlRNAd.js";const m=JSON.parse('{"title":"Paramètres","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/settings.md","filePath":"fr/guide/settings.md"}'),o={name:"fr/guide/settings.md"};function n(i,e,l,c,u,d){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="parametres" tabindex="-1">Paramètres <a class="header-anchor" href="#parametres" aria-label="Permalink to &quot;Paramètres&quot;">​</a></h1><p>Les <strong>Paramètres</strong> (<code>/settings/…</code>) sont découpés en cinq sections, en onglets sur ordinateur et listées dans la page <strong>Plus</strong> sur mobile :</p><table tabindex="0"><thead><tr><th>Section</th><th>Adresse</th></tr></thead><tbody><tr><td><a href="#compte">Compte</a></td><td><code>/settings/account</code></td></tr><tr><td><a href="#securite">Sécurité</a></td><td><code>/settings/security</code></td></tr><tr><td><a href="#comptes-gmail">Comptes Gmail</a></td><td><code>/settings/gmail</code></td></tr><tr><td><a href="#notifications-webhooks">Notifications &amp; webhooks</a></td><td><code>/settings/notifications</code></td></tr><tr><td><a href="#donnees">Données</a></td><td><code>/settings/data</code></td></tr><tr><td><a href="#a-propos">À propos</a></td><td><code>/settings/about</code></td></tr></tbody></table><hr><h2 id="compte" tabindex="-1">Compte <a class="header-anchor" href="#compte" aria-label="Permalink to &quot;Compte&quot;">​</a></h2><ul><li><strong>Profil</strong> : avatar, nom, email, et l&#39;espace occupé par vos archives (« Archives : X utilisés sur Y », quota fixé par l&#39;administrateur).</li><li><strong>Langue et apparence</strong> : <strong>Langue</strong> (français / anglais) et <strong>Thème</strong> (<strong>Système</strong>, <strong>Clair</strong>, <strong>Sombre</strong>). La langue et le mode sombre sont aussi dans le menu de l&#39;avatar.</li><li><strong>Lecture</strong> : <ul><li><strong>Afficher les images distantes</strong> : désactivé par défaut, car ces images servent souvent à savoir quand vous ouvrez un mail. Un bouton « Afficher » reste disponible dans chaque mail.</li><li><strong>Raccourcis clavier à une touche</strong> : active les <a href="./mails.html#raccourcis-clavier">raccourcis de Mails</a> (<code>j</code>/<code>k</code>, <code>e</code>, <code>#</code>, <code>r</code>, <code>u</code>, <code>/</code>). À désactiver si vous utilisez une commande vocale.</li></ul></li></ul><hr><h2 id="securite" tabindex="-1">Sécurité <a class="header-anchor" href="#securite" aria-label="Permalink to &quot;Sécurité&quot;">​</a></h2><h3 id="mot-de-passe" tabindex="-1">Mot de passe <a class="header-anchor" href="#mot-de-passe" aria-label="Permalink to &quot;Mot de passe&quot;">​</a></h3><p>Comptes locaux uniquement (un compte Google ou SSO n&#39;a pas de mot de passe Nid) : <strong>Mot de passe actuel</strong>, <strong>Nouveau mot de passe</strong> (8 caractères minimum) et sa confirmation, puis <strong>Changer le mot de passe</strong>. Vos autres sessions ouvertes sont déconnectées.</p><p>Mot de passe oublié : sur l&#39;écran de connexion, <strong>Mot de passe oublié ?</strong> envoie un lien valable 1 heure (si l&#39;instance a un serveur SMTP, voir <a href="./../installation/configuration.html#e-mail-smtp">Configuration</a>). Sinon, demandez à un administrateur de le réinitialiser (<a href="./admin.html#utilisateurs">Administration</a>).</p><h3 id="passkeys" tabindex="-1">Passkeys <a class="header-anchor" href="#passkeys" aria-label="Permalink to &quot;Passkeys&quot;">​</a></h3><p>Une passkey remplace mot de passe et code 2FA : on se connecte avec le code ou la biométrie de l&#39;appareil (Face ID, Windows Hello, empreinte, clé de sécurité). Donnez-lui un <strong>Nom</strong> (ex. « iPhone »), puis <strong>Ajouter une passkey</strong> et suivez la fenêtre du navigateur. Ensuite, sur l&#39;écran de connexion : <strong>Se connecter avec une passkey</strong>, sans saisir d&#39;e-mail. La liste indique la dernière utilisation de chaque passkey ; l&#39;icône corbeille la supprime.</p><p>La carte n&#39;apparaît que si le navigateur gère les passkeys. Une passkey est liée à l&#39;adresse de l&#39;instance : si cette adresse change, il faut en recréer.</p><h3 id="authentification-a-deux-facteurs-2fa" tabindex="-1">Authentification à deux facteurs (2FA) <a class="header-anchor" href="#authentification-a-deux-facteurs-2fa" aria-label="Permalink to &quot;Authentification à deux facteurs (2FA)&quot;">​</a></h3><ol><li>Cliquez sur <strong>Configurer la 2FA</strong></li><li>Scannez le QR code avec votre application d&#39;authentification (Google Authenticator, Aegis, Authy…), ou saisissez la clé affichée</li><li>Saisissez le <strong>Code à 6 chiffres</strong> puis <strong>Vérifier et activer</strong></li></ol><p>Une fois activée, un code est demandé à chaque connexion, y compris avec Google ou un autre fournisseur (SSO). Pour la désactiver, saisissez un code puis <strong>Désactiver la 2FA</strong>.</p><h3 id="jetons-d-api" tabindex="-1">Jetons d&#39;API <a class="header-anchor" href="#jetons-d-api" aria-label="Permalink to &quot;Jetons d&#39;API&quot;">​</a></h3><p>Pour Home Assistant ou un script. Donnez un <strong>Nom</strong> au jeton, choisissez ses <strong>Droits</strong> (<em>Lecture seule</em>, ou <em>Lecture et actions</em> pour lancer des jobs ou des règles) et son <strong>Expiration</strong>, puis <strong>Créer le jeton</strong>. Copiez-le tout de suite : il n&#39;est affiché qu&#39;une fois. Envoyez-le dans l&#39;en-tête <code>Authorization: Bearer nid_…</code>. Un jeton n&#39;a jamais accès à la sécurité du compte, à l&#39;administration, au chiffrement, aux webhooks ni aux liens de partage. La liste indique la dernière utilisation de chaque jeton ; l&#39;icône corbeille le révoque. Voir la <a href="./../technical/api/auth.html#jetons-d-api">référence API</a>.</p><h3 id="liens-de-partage" tabindex="-1">Liens de partage <a class="header-anchor" href="#liens-de-partage" aria-label="Permalink to &quot;Liens de partage&quot;">​</a></h3><p>Nombre de liens de partage actifs vers vos mails archivés, avec le lien <strong>Gérer les liens de partage dans Archives</strong> (onglet <a href="./archives.html#onglet-partages">Partages</a>).</p><hr><h2 id="comptes-gmail" tabindex="-1">Comptes Gmail <a class="header-anchor" href="#comptes-gmail" aria-label="Permalink to &quot;Comptes Gmail&quot;">​</a></h2><p>Chaque compte connecté affiche :</p><ul><li>son état : <strong>Synchronisé</strong>, <strong>Action requise</strong> (Google a retiré l&#39;accès de Nid : reconnectez le compte pour reprendre la synchronisation et les sauvegardes) ou <strong>Déconnecté</strong> ;</li><li><strong>Synchronisation</strong> : « Dernière synchro … », nombre de mails dans Gmail, bouton <strong>Synchroniser maintenant</strong> ;</li><li><strong>Sauvegarde NAS</strong> : <strong>Sauvegarde automatique</strong> (sauvegarde sur le NAS les nouveaux mails du compte) et sa <strong>Fréquence</strong> : Toutes les heures, Toutes les 6 heures, Une fois par jour ;</li><li><strong>Reconnecter avec Google</strong> et <strong>Déconnecter</strong>.</li></ul><p><strong>Déconnecter</strong> demande confirmation : Nid arrête la synchronisation et les sauvegardes de ce compte, mais ses archives restent sur le NAS et dans Nid. Les pages qui ont besoin de Gmail (Vue d&#39;ensemble, Mails, Nettoyage, Règles) affichent alors « … est déconnecté » avec <strong>Reconnecter dans Paramètres</strong> ; <a href="./archives.html">Archives</a> reste consultable.</p><p><strong>Ajouter un compte Gmail</strong> connecte un nouveau compte, dans la limite affichée (« N / max comptes »). Accès demandés : <code>gmail.modify</code>, <code>gmail.labels</code>.</p><p>Au retour de Google, un assistant <strong>Configurer le compte</strong> s&#39;ouvre pour ce nouveau compte (pas lors d&#39;une reconnexion) :</p><ol><li><strong>Connexion Google</strong> — déjà faite ;</li><li><strong>Sauvegarde</strong> — sauvegarde automatique et fréquence, puis la <strong>première sauvegarde</strong> : les 12 derniers mois (par défaut), toute la boîte, ou plus tard ;</li><li><strong>Règles</strong> — des règles de départ à cocher (nettoyage des promotions, des vieilles newsletters, archivage des factures…), chacune avec son action, sa fréquence et le nombre approximatif de mails concernés aujourd&#39;hui ;</li><li><strong>Récapitulatif</strong> — <strong>Terminer</strong> applique tout. « Supprimer » place les mails dans la corbeille Gmail (30 jours).</li></ol><p>Chaque étape peut être passée ; <strong>Plus tard</strong> ferme l&#39;assistant sans rien enregistrer. Les règles créées se modifient ensuite dans <a href="./rules.html">Règles &amp; libellés</a>.</p><p><strong>Ajouter un compte IMAP</strong> connecte un compte d&#39;un autre fournisseur (OVH, Infomaniak, Fastmail, Outlook…) en <strong>archivage seul</strong> : adresse, serveur IMAP, port (993 par défaut), connexion chiffrée, identifiant (l&#39;adresse par défaut) et mot de passe — avec la double authentification, un mot de passe d&#39;application. Nid teste la connexion avant d&#39;enregistrer et affiche la raison donnée par le serveur s&#39;il refuse. Le mot de passe est stocké chiffré. Le même assistant s&#39;ouvre ensuite (sauvegarde automatique, première sauvegarde : toute la boîte ou plus tard ; pas de règles, réservées à Gmail).</p><p>Un compte IMAP porte le badge <strong>IMAP · archivage</strong>. Ses dossiers sont sauvegardés sur le NAS et deviennent des libellés dans <a href="./archives.html">Archives</a> ; la Vue d&#39;ensemble n&#39;affiche que ses chiffres d&#39;archives, et Mails, Nettoyage et Règles renvoient vers Archives. Si le serveur refuse la connexion (mot de passe changé), le compte passe en <strong>Action requise</strong> : <strong>Mettre à jour le serveur ou le mot de passe</strong>.</p><h3 id="partager-un-compte-en-lecture-seule" tabindex="-1">Partager un compte en lecture seule <a class="header-anchor" href="#partager-un-compte-en-lecture-seule" aria-label="Permalink to &quot;Partager un compte en lecture seule&quot;">​</a></h3><p>Le bloc <strong>Partage</strong> de chaque compte donne accès à ses archives à d&#39;autres utilisateurs de <strong>cette instance Nid</strong> : saisissez l&#39;adresse de leur compte Nid puis <strong>Partager</strong>. Ils peuvent rechercher et lire les archives (pièces jointes, conversations, contacts, libellés et tags), <strong>sans rien modifier</strong> ni accéder à Gmail : pas de suppression, de tags, de restauration, d&#39;export, de lien de partage, ni de sauvegarde. Le bouton ✕ d&#39;une personne lui retire l&#39;accès.</p><p>Pour celui qui reçoit le partage, le compte apparaît dans le sélecteur de compte avec « (partagé par …) » : <a href="./archives.html">Archives</a> s&#39;ouvre en lecture seule (onglets Mails et Contacts) et les autres pages indiquent que seules ses archives sont accessibles. La carte <strong>Partagés avec moi</strong> liste ces comptes ; <strong>Ne plus voir</strong> retire le partage de son côté.</p><hr><h2 id="notifications-webhooks" tabindex="-1">Notifications &amp; webhooks <a class="header-anchor" href="#notifications-webhooks" aria-label="Permalink to &quot;Notifications &amp; webhooks&quot;">​</a></h2><p>Préférences par événement (in-app, toast) et webhooks vers Discord, Slack, ntfy ou une URL à vous : voir <a href="./notifications.html">Notifications</a>.</p><hr><h2 id="donnees" tabindex="-1">Données <a class="header-anchor" href="#donnees" aria-label="Permalink to &quot;Données&quot;">​</a></h2><p>Les imports et l&#39;export portent sur le compte Gmail actif.</p><h3 id="importer-un-fichier-mbox" tabindex="-1">Importer un fichier mbox <a class="header-anchor" href="#importer-un-fichier-mbox" aria-label="Permalink to &quot;Importer un fichier mbox&quot;">​</a></h3><p>Export Google Takeout ou autre client mail, ajouté aux archives du compte (libellés Gmail conservés). Cliquez sur <strong>Choisir un fichier .mbox</strong> ; l&#39;import se suit dans <a href="./activity.html">Activité</a>.</p><div class="tip custom-block"><p class="custom-block-title">Google Takeout</p><ol><li>Allez sur <a href="https://takeout.google.com" target="_blank" rel="noreferrer">takeout.google.com</a></li><li>Sélectionnez uniquement <strong>Gmail</strong>, au format <strong>mbox</strong></li><li>Téléchargez l&#39;archive et importez le fichier <code>.mbox</code> dans Nid</li></ol></div><h3 id="importer-depuis-un-serveur-imap" tabindex="-1">Importer depuis un serveur IMAP <a class="header-anchor" href="#importer-depuis-un-serveur-imap" aria-label="Permalink to &quot;Importer depuis un serveur IMAP&quot;">​</a></h3><p>Copie les mails d&#39;une autre boîte (Outlook, Fastmail…) dans les archives du compte. Champs : <strong>Serveur</strong>, <strong>Port</strong>, <strong>Identifiant</strong>, <strong>Mot de passe</strong>, <strong>Dossier</strong>, <strong>Nombre maximal de mails</strong>, <strong>Connexion chiffrée (TLS)</strong>, puis <strong>Lancer l&#39;import</strong>. Le mot de passe n&#39;est pas conservé.</p><div class="warning custom-block"><p class="custom-block-title">Mot de passe d&#39;application</p><p>De nombreux fournisseurs (Google, Outlook, Yahoo) exigent un <strong>mot de passe d&#39;application</strong> plutôt que votre mot de passe habituel.</p></div><h3 id="exporter-les-archives" tabindex="-1">Exporter les archives <a class="header-anchor" href="#exporter-les-archives" aria-label="Permalink to &quot;Exporter les archives&quot;">​</a></h3><p><strong>Exporter (.mbox)</strong> : toutes les archives du compte dans un fichier .mbox, lisible par Thunderbird ou Apple Mail.</p><h3 id="archives-chiffrees" tabindex="-1">Archives chiffrées <a class="header-anchor" href="#archives-chiffrees" aria-label="Permalink to &quot;Archives chiffrées&quot;">​</a></h3><p>Affichée seulement si le compte a encore des archives chiffrées par l&#39;ancien chiffrement, retiré de Nid : il laissait en clair objet, expéditeur et destinataires, et empêchait la lecture, la recherche et la restauration. Saisissez la <strong>Phrase secrète</strong> puis <strong>Déchiffrer</strong> : les archives sont remises en clair en tâche de fond (suivi dans <a href="./activity.html">Activité</a>), puis redeviennent lisibles et cherchables. Pour protéger les archives au repos, chiffrez plutôt le volume du NAS.</p><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>Vos règles et webhooks dans un fichier JSON, pour les sauvegarder ou les reprendre sur une autre instance : <strong>Exporter la configuration</strong> / <strong>Importer une configuration</strong>.</p><h3 id="mes-donnees-rgpd" tabindex="-1">Mes données (RGPD) <a class="header-anchor" href="#mes-donnees-rgpd" aria-label="Permalink to &quot;Mes données (RGPD)&quot;">​</a></h3><p><strong>Exporter mes données</strong> : tout ce que Nid conserve sur vous dans un fichier JSON (profil, comptes Gmail, règles, métadonnées des archives, journal d&#39;activité…). Le contenu des mails s&#39;exporte en .mbox (ci-dessus) ; les secrets (mots de passe, jetons) sont exclus.</p><h3 id="supprimer-mon-compte" tabindex="-1">Supprimer mon compte <a class="header-anchor" href="#supprimer-mon-compte" aria-label="Permalink to &quot;Supprimer mon compte&quot;">​</a></h3><p>Saisissez votre mot de passe (ou, pour un compte Google/SSO, votre adresse e-mail), puis <strong>Supprimer définitivement mon compte</strong> et confirmez. Votre compte, vos comptes Gmail connectés, vos archives et vos règles sont supprimés de Nid ; rien n&#39;est supprimé dans Gmail. Le dernier administrateur de l&#39;instance ne peut pas supprimer son compte.</p><hr><h2 id="a-propos" tabindex="-1">À propos <a class="header-anchor" href="#a-propos" aria-label="Permalink to &quot;À propos&quot;">​</a></h2><ul><li><strong>Version</strong> : la version de Nid installée, et si une plus récente est publiée (vérification deux fois par jour, avec la date de la dernière). Quand une mise à jour existe, la carte donne le lien vers les nouveautés et la commande à lancer.</li><li><strong>Ce que Nid contacte</strong> : la liste des services externes auxquels l&#39;instance parle (Google, ghcr.io pour la vérification des versions, votre SMTP, vos webhooks, les fournisseurs SSO configurés). Aucune télémétrie.</li><li><strong>Projet</strong> : licence MIT, code source, historique des versions, signalement d&#39;un problème.</li></ul>',60)])])}const g=s(o,[["render",n]]);export{m as __pageData,g as default};
